    expect(html).toContain("Feature not found.");
  });

  it("renders retry button when error is retryable", () => {
    mockUseFeatureDetail.mockReturnValue({
      feature: null,
      loading: false,
      error: { code: "TIMEOUT", message: "Timed out.", retryable: true },
      reload: vi.fn(),
