      reload: vi.fn(),
    });

    const html = renderToStaticMarkup(
      React.createElement(FeatureTabView, {
        workspaceId: "ws-1",
        featureId: "feat-uuid-1",
      }),
    );
    expect(html).not.toContain("Retry");
  });
});

