// ─── FeatureTabView — tasks panel ────────────────────────────────────────────

describe("FeatureTabView — tasks panel", () => {
  beforeEach(() => {
    mockUseFeatureTask.mockReturnValue({
      task: null,
      loading: false,
      error: null,
      reload: vi.fn(),
    });
